const output = $input.first().json.output || '';

// Extraer datos del lead si el agente incluyó el marcador
const match = output.match(/\[MATTERA_LEAD\|nombre=([^|]+)\|empresa=([^|]+)\|whatsapp=([^\]]+)\]/);

// Limpiar el marcador de la respuesta que recibirá el usuario
const cleanResponse = output.replace(/\[MATTERA_LEAD[^\]]*\]/g, '').trim();

let leadData = null;
if(match) {
  leadData = {
    nombre: match[1].trim(),
    empresa: match[2].trim(),
    whatsapp: match[3].trim()
  };
}

return [{ json: { response: cleanResponse, lead: leadData, hasLead: !!match } }];

